INTRO = "Opening her heart to Baek Seung-chan, Cindy reveals why she avoided amusement parks for a decade: after begging her parents to visit on her birthday and moving to Seoul as CEO Byun's trainee, she lost her parents in an accident while they were traveling to see her. Seung-chan's gentle words lift ten years of guilt."

STORY = [
    ('cindy', '아무리 생각해도 여기 오지 않았으면 좋았을 것 같아요. 우리 집 춘천이었는데 그날 내 생일이라고 졸라서 여기 온 거고.', 'No matter how much I think about it, I wish I had never come here—our home was in Chuncheon, and I pestered my parents to bring me for my birthday.', [(975, '아무리 생각해도 여기 오지 않았으면 좋았을 것 같아요'), (976, '우리 집 춘천이었어요'), (977, '그날 내 생일이라고')], ''),
    ('cindy', '변 대표님 만난 다음부터는 서울에 있는 연습실에서 살다시피 했어요. 부모님이 2주에 한 번씩 나 보러 서울에 다녀가셨고.', 'After meeting CEO Byun, I practically lived in a Seoul practice room while my parents came up to Seoul every two weeks to see me.', [(978, '변 대표님 만난 다음부터는 서울에 있는 연습실에서 살다시피 했어요'), (979, '2주에 한 번씩 나 보러 서울에 다녀가셨고')], ''),
    ('byun', '신디야, 이제 내가 네 엄마야. 엄마만 믿고 따라오면 돼.', 'Cindy, from now on I am your mother—just trust Mom and follow me.', [(980, '신디야'), (981, '이제 내가 네 엄마야'), (982, '엄마만 믿고 따라오면 돼')], ''),
    ('cindy', '내가 그날 여기 오자고 조르지만 않았으면, 변 대표를 만나지 않았으면, 엄마 아빠랑 헤어져서 살지 않았으면…', 'If only I had not begged to come here that day, had never met CEO Byun, had never lived apart from Mom and Dad…', [(984, '그날 여기 오자고 조르지만 않았으면'), (986, '변 대표를 만나지 않았으면'), (988, '엄마 아빠랑 헤어져서 살지 않았으면')], ''),
    ('cindy', '그날 그런 사고가 나지 않았으면 얼마나 좋았을까.', 'How wonderful would it have been if that accident had never happened that day?', [(990, '그날 그런 사고가'), (991, '나지 않았으면'), (992, '얼마나 좋았을까')], ''),
    ('cindy', '백 번 천 번 생각한다고 그렇게 될 수 있는 것도 아닌데 난 10년 동안 매일 밤 그 생각을 했어요. 그 생각만 하면 잠이 안 왔어.', 'Thinking it a hundred or a thousand times cannot change anything, yet I thought it every single night for ten years—and could never fall asleep.', [(993, '백번 천번 생각한다고'), (994, '그렇게 될 수 있는 것도 아닌데'), (995, '난 10년 동안 매일 밤 그 생각을 했어요'), (996, '그 생각만 하면 잠이 안 왔어')], ''),
    ('seungchan', '신디 씨 잘못 아니에요. 부모님도 그렇게 생각하지 않으실 거고 만약에라는 생각을 이제 그만하길 바라실 거예요.', 'It is not your fault, Ms. Cindy—your parents would never think that either, and they would want you to stop asking "what if" now.', [(997, '신디씨 잘못 아니에요'), (998, '부모님도 그렇게 생각하지 않으실 거고'), (999, '생각을 이제 그만하길 바라실 거예요')], ''),
    ('seungchan', '오히려 지금까지 혼자 참 잘했고 수고했다고 하실 겁니다.', 'Instead, they would tell you that you have done wonderfully all on your own and worked so hard.', [(1000, '오히려 지금까지 혼자 참 잘했고')], ''),
    ('cindy', '나 좀 잡아줄래요? 내 인생에 여기 올 일 다시는 없다고 생각했거든요. 오늘 오길 잘한 것 같아.', 'Could you hold my hand? I thought I would never set foot here again in my life—I am really glad I came today.', [(1002, '나 좀 잡아줄래요'), (1003, '내 인생에 여기 올 일 다시는 없다고 생각했거든요'), (1004, '오늘 오길 잘한 것 같아')], ''),
    ('cindy', '이제는 놀이공원 하면 피디님 생각날 것 같아.', 'From now on, whenever someone mentions an amusement park, I think I will remember you, Producer.', [(1006, '이제는 놀이공원 하면 피디님 생각날 것 같아')], ''),
    ('seungchan', '제가요?', 'Me?', [(1007, '제가요')], ''),
]

